import { Group, Mesh, PlaneGeometry, Color, SRGBColorSpace, ClampToEdgeWrapping } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color, float, vec2, sin, dot, fract } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  const root = new THREE.Group();
  root.name = 'collection-card-1-label';

  const content = new THREE.Group();
  root.add(content);

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // ---- backdrop plate: engineered gradient + subtle grain ----
  const plateW = 1.7;
  const plateH = 1.05;
  const plateGeo = new THREE.PlaneGeometry(plateW, plateH, 1, 1);
  const plateMat = new MeshBasicNodeMaterial({ transparent: true });

  const topColor = color(colors.surface);
  const bottomColor = color(colors.ink);
  const vUv = uv();
  const gradient = mix(bottomColor, topColor, vUv.y);

  const grainSeed = vec2(vUv.x.mul(512.0), vUv.y.mul(320.0));
  const grainHash = fract(sin(dot(grainSeed, vec2(12.9898, 78.233))).mul(43758.5453));
  const grain = grainHash.sub(0.5).mul(0.035);

  plateMat.colorNode = gradient.add(grain);
  plateMat.opacityNode = float(0.92);

  const plate = new THREE.Mesh(plateGeo, plateMat);
  plate.position.set(0, 0, -0.02);
  content.add(plate);

  // ---- accent image plane (atlas-region sized to source rect aspect) ----
  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = rect.w / rect.h;
  const imgH = 0.62;
  const imgW = imgH * aspect;
  const imgGeo = new THREE.PlaneGeometry(imgW, imgH, 1, 1);
  const imgMat = new MeshBasicNodeMaterial({ transparent: true });
  const imgMesh = new THREE.Mesh(imgGeo, imgMat);
  imgMesh.position.set(0, 0.14, 0.0);
  content.add(imgMesh);

  let loadedTexture = null;
  ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      loadedTexture = tex;
      tex.colorSpace = THREE.SRGBColorSpace;
      const iw = tex.image?.width ?? rect.w;
      const ih = tex.image?.height ?? rect.h;
      tex.wrapS = THREE.ClampToEdgeWrapping;
      tex.wrapT = THREE.ClampToEdgeWrapping;
      tex.repeat.set(rect.w / iw, rect.h / ih);
      tex.offset.set(rect.x / iw, 1 - (rect.y + rect.h) / ih);
      tex.needsUpdate = true;
      imgMat.map = tex;
      imgMat.needsUpdate = true;
    })
    .catch(() => {});

  // ---- headline label text ----
  const items = config.textContent ?? config?.intent?.visualSpec?.textContent ?? [
    { text: 'Collection 1', role: 'headline', typography: { fontSize: 39 } },
  ];
  const headline = items.find((i) => i.role === 'headline') ?? items[0];
  const fontSizePx = headline?.typography?.fontSize ?? 39;

  const textNode = ctx.fontAtlas.createText(headline?.text ?? 'Collection 1', {
    fontSize: fontSizePx,
    color: colors.paper,
    align: 'center',
  });
  textNode.position.set(0, -0.34, 0.01);
  content.add(textNode);

  // ---- accent underline bar (single accent element, <=10% of frame) ----
  const barGeo = new THREE.PlaneGeometry(0.34, 0.018, 1, 1);
  const barMat = new MeshBasicNodeMaterial({ color: new THREE.Color(colors.accent) });
  const bar = new THREE.Mesh(barGeo, barMat);
  bar.position.set(0, -0.46, 0.01);
  content.add(bar);

  // ---- weighted-settle entrance (applied to inner content, not root) ----
  content.scale.setScalar(0.96);
  content.position.y = -0.16;

  const tl = gsap.timeline();
  tl.to(content.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
  tl.to(content.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    plateGeo.dispose();
    plateMat.dispose();
    imgGeo.dispose();
    imgMat.dispose();
    barGeo.dispose();
    barMat.dispose();
    if (loadedTexture) loadedTexture.dispose();
    if (textNode?.geometry?.dispose) textNode.geometry.dispose();
    if (textNode?.material?.dispose) textNode.material.dispose();
  };

  return root;
}
